import { hiprint, defaultElementTypeProvider } from './hiprint/hiprint.bundle.js'
// 调用浏览器打印js
import "./hiprint/plugins/jquery.hiwprint.js";
// 默认配置
import "./hiprint/hiprint.config";
// 样式
import "./hiprint/css/hiprint.css"
import "./hiprint/css/print-lock.css"

import { version } from '../package.json'

/**
 * 自动连接 / 连接
 * cb: 连接回调， (status, msg) {
 *   // status: true/false
 *   // msg: status == true 时 返回socket.connect回调 e
 * }
 */
let autoConnect = function (cb) {
  console.log('autoConnect');
  window.autoConnect = true;
  window.hiwebSocket && window.hiwebSocket.hasIo() && window.hiwebSocket.start(cb);
};

/**
 * 取消自动连接 / 断开连接
 */
let disAutoConnect = function () {
  console.log('disAutoConnect');
  window.autoConnect = false;
  window.hiwebSocket && window.hiwebSocket.hasIo() && window.hiwebSocket.stop();
};

// Vue 3 插件签名：第一参数是 app 实例
// 通过 app.config.globalProperties 注册全局属性（$hiPrint / $print / $print2）
let hiPrintPlugin = {
  disAutoConnect,
  install: function (app, name = '$hiPrint', autoConnect = true) {
    if (!autoConnect) {
      disAutoConnect();
    }
    app.config.globalProperties[name] = hiprint;
    /**
     * 预览打印，调起系统打印预览
     * provider 左侧拖拽元素
     * template 模版json字符串
     * args 打印数据data, options,
     */
    app.config.globalProperties.$print = function (provider = defaultElementTypeProvider, template, ...args) {
      hiprint.init({
        providers: [new provider()]
      });
      var hiprintTemplate = new hiprint.PrintTemplate({
        template: template,
      });
      hiprintTemplate.print(...args);
      return hiprintTemplate;
    };
    /**
     * 单模版直接打印， 需客户端支持
     * provider 左侧拖拽项对象
     * template 模版json字符串
     * args 打印数据data, options,
     */
    app.config.globalProperties.$print2 = function (provider = defaultElementTypeProvider, template, ...args) {
      hiprint.init({
        providers: [new provider()]
      });
      var hiprintTemplate = new hiprint.PrintTemplate({
        template: template,
      });
      hiprintTemplate.print2(...args);
      return hiprintTemplate;
    };
  }
}

hiprint.version = version

window.hiprint = hiprint;
window.vue3Hiprint = hiprint;
export {
  autoConnect,
  disAutoConnect,
  hiprint,
  hiPrintPlugin,
  defaultElementTypeProvider,
}